-- Take Down Tethyr! (27222, Theramore) : la quete se rendait sans rien faire (aucun objectif, aucun drapeau d evenement) et
-- Tethyr comme les Tireurs de Theramore n avaient aucune IA. Rencontre reprise du TDB 7.3.5 de TrinityCore (735.00) :
-- appel des tireurs, canons, trajet et sorts de Tethyr, echec si les tireurs meurent, credit chez Major Mills a sa mort.
-- Adaptations : quete 11198 (DEPRECATED) -> 27222 ; GUID TDB -> les notres (Major Mills 31075 -> 255200, canons
-- 186432 10824/10227/11186 -> 173237/173238/173239). Textes et point de trajet deja presents chez nous.
UPDATE `creature_template` SET `AIName` = 'SmartAI', `ScriptName` = '' WHERE `entry` IN (23899, 23900, 23905);
UPDATE `quest_template_addon` SET `SpecialFlags` = `SpecialFlags` | 2 WHERE `ID` = 27222;
DELETE FROM `smart_scripts` WHERE (`entryorguid` IN (23899, 23900, 23905) AND `source_type` = 0) OR (`entryorguid` IN (2389900, 2389901, 2390000, 2390001, 2390500, 2390501) AND `source_type` = 9);
